def evaluate_flag(flag, subject, now):
    def deny(reason):
        return {"enabled": False, "reason": reason}
    if flag["kill"]:
        return deny("kill")
    if not flag["enabled"]:
        return deny("disabled")
    if now < flag["start"] or (flag["end"] is not None and now >= flag["end"]):
        return deny("window")
    if flag["environments"] and subject["environment"] not in flag["environments"]:
        return deny("environment")
    groups = set(subject["groups"])
    if groups.intersection(flag["denied_groups"]):
        return deny("denied_group")
    if subject["staff"] and flag["staff_bypass"]:
        return {"enabled": True, "reason": "staff"}
    if flag["allowed_groups"] and not groups.intersection(flag["allowed_groups"]):
        return deny("groups")
    if (subject["id"] + flag["salt"]) % 100 >= flag["rollout"]:
        return deny("rollout")
    return {"enabled": True, "reason": "enabled"}

