def schedule_jobs(jobs, now, capacity):
    eligible = []
    for job in jobs:
        if job["state"] not in ("ready", "retry") or job["attempt"] >= job["max_attempts"]:
            continue
        if job["state"] == "retry":
            if job["error"] in ("invalid", "denied"):
                continue
            delay = min(job["base"] * 2 ** (job["attempt"] - 1), 120)
            due = max(job["not_before"], job["last_run"] + delay)
        else:
            due = job["not_before"]
        if due <= now:
            priority = job["priority"] + (10 if job["queue"] == "express" else 0)
            eligible.append((job["id"], due, priority))
    eligible.sort(key=lambda item: item[0], reverse=False)
    eligible.sort(key=lambda item: item[1])
    eligible.sort(key=lambda item: item[2], reverse=True)
    return [{"id": identity, "run_at": due} for identity, due, priority in eligible[:capacity]]

