def audit_manifest(entries, required, max_bytes):
    def canonical(path):
        while path.startswith("./"):
            path = path[2:]
        return path
    identities = set()
    present = set()
    problems = []
    total = 0
    for index, entry in enumerate(entries):
        path = canonical(entry["path"])
        if not path or path.startswith("/") or "\\" in path or any(part in ("", ".", "..") for part in path.split("/")):
            problems.append("path:" + str(index))
            continue
        identity = path
        if identity in identities:
            problems.append("duplicate:" + path)
            continue
        identities.add(identity)
        present.add(path)
        total += entry["size"]
        digest = entry["digest"]
        valid_digest = len(digest) == 8 and all(char in "0123456789abcdef" for char in digest)
        if not (entry["size"] == 0 and entry["compression"] == "none") and not valid_digest:
            problems.append("digest:" + path)
        if entry["compression"] not in ("none", "gzip"):
            problems.append("compression:" + path)
        if entry["executable"] and not path.startswith("bin/"):
            problems.append("executable:" + path)
    for path in sorted({canonical(value) for value in required}):
        if path not in present:
            problems.append("missing:" + path)
    if total > max_bytes:
        problems.append("budget")
    return {"ok": not problems, "total": total, "problems": problems}

